var e={eyebrow:`الثقة والأمان`,titleLines:[`أمان مدمج`,`في كل`,`عملية نشر.`],lede:`تتضمن كل عملية نشر التشفير وسجلات الإجابات وحجب PII. تحتفظ NeuralSeek بتقارير SOC 1 و SOC 2 Type II وتتوافق مع HIPAA.`,chapters:[{id:`encrypted`,title:`مشفرة ومعزولة`,body:`TLS 1.2+ أثناء النقل، و AES-256 أثناء التخزين، وتكامل مع خدمة إدارة المفاتيح لديك، ومفاتيح منفصلة لكل عميل. لا تُستخدم prompts ومستنداتك لتدريب النماذج أبدًا.`,cta:`اطلع على الضوابط`,href:`/trust/`,form:`container`,image:`platform/seek/semantic-retrieval`,breadcrumb:`security / isolation`,alt:`لوحة حوكمة تعرض الثقة والتغطية وتكلفة tokens ونسبة إصابة الذاكرة المؤقتة`},{id:`audited`,title:`مدقَّقة ومحجوبة`,body:`يُسجَّل كل سؤال وإجابة ودرجة وتغيير في الإعدادات مع ختم زمني، ويمكن تصديرها إلى SIEM لديك. يمكن الإشارة إلى البيانات الشخصية أو حجبها أو إخفاؤها أو حذفها، بحسب الموضوع.`,cta:`اطلع على سجل التدقيق`,href:`/trust/#trust-controls`,form:`layers`,image:`platform/governance/agentic-governance`,breadcrumb:`governance / policy`,alt:`لوحات مقارنة النماذج تعرض الثقة وحل الأسئلة ومقاييس حقن prompt`},{id:`everywhere`,title:`الضوابط نفسها في كل مكان`,body:`SaaS وسحابة خاصة وسحابة سيادية و OpenShift أو داخل المؤسسة في بيئة معزولة تمامًا عن الإنترنت. تأتي كل عملية نشر بحواجز الحماية وسجل التدقيق وضوابط الحجب نفسها.`,cta:`اطلع على خيارات النشر`,href:`/platform/deployment/`,form:`fanout`,image:null,breadcrumb:`deployment / options`,alt:``}],cards:[{id:`encryption`,image:`platform/seek/platform-semantic-configuration`,span:`sm:col-span-2`,glyph:`shield`,title:`تشفير أثناء النقل وعند التخزين`,body:`TLS 1.2+ لكل حركة الشبكة. والبيانات المخزنة مشفرة وفق AES-256. وتتكامل NeuralSeek مع خدمة إدارة المفاتيح لديك.`},{id:`isolation`,image:`platform/deployment/platform-secrets`,span:`sm:col-span-2`,glyph:`container`,title:`عزل لكل عميل`,body:`مفاتيح منفصلة لكل عميل. تبقى prompts ومستنداتك ومخرجاتك في بيئتك ولا تُستخدم لتدريب النماذج أبدًا.`},{id:`audit`,image:`platform/governance/platform-data-lineage`,span:`sm:col-span-2`,glyph:`layers`,title:`سجل تدقيق كامل`,body:`يُسجَّل كل سؤال وإجابة ودرجة وتغيير في الإعدادات مع ختم زمني ونسبته إلى صاحبه. صدّره إلى S3 أو Splunk أو Datadog.`},{id:`pii`,image:`platform/governance/agentic-governance`,span:`sm:col-span-3`,glyph:`grid`,title:`اكتشاف PII وحجبها`,body:`الإشارة إلى البيانات الشخصية أو حجبها أو إخفاؤها أو حذفها، وفق إعداد لكل موضوع.`},{id:`deployment`,image:`platform/maistro/platform-agent-maistro`,span:`sm:col-span-3`,glyph:`fanout`,title:`انشر حيث تحتاج`,body:`SaaS وسحابة خاصة وسحابة سيادية و OpenShift أو داخل المؤسسة في بيئة معزولة تمامًا عن الإنترنت. تعمل في أي بيئة معزولة دون الحاجة إلى اتصال بالإنترنت.`},{id:`no-training`,image:`platform/seek/semantic-retrieval`,span:`sm:col-span-6`,glyph:`shield`,title:`لا تدريب على بياناتك`,body:`تبقى بياناتك ملكًا لك. لا تستخدم NeuralSeek ولا معالجو البيانات من الباطن لديها prompts أو مستنداتك أو سجلاتك لتدريب النماذج.`}]};export{e as trust};